//  type-genericity (sampler2D / usampler2D 切换). Static file + uniform 是最简最快的方案.
//
//  Uniforms:
//    InputBuffer    — 输入 (post-demosaic RGBA16F)
//    uNoiseS/O      — adaptive 噪声模型 (basePipeline.noiseS/O / scale)
//    uKernelSize    — gaussian spatial sigma (1 + sqrt(noiseMpy)*24)
//    uKsize         — 卷积核 half size: KSIZE = (MSIZE-1)/2, MSIZE in [7,21]
//    uMoire         — 色摩尔抑制强度 (0.0 for pre-pass, 1.5 for main pass)
//    uLuma          — 亮度去噪强度 (0..2, 默认 0.8)
// ════════════════════════════════════════════════════════════════════════════
precision highp float;

